#include "runtime.h"
#include <string.h>
void wena_server_runtime_init(WenaServerRuntime *r){if(r){memset(r,0,sizeof(*r));wena_http_listener_init(&r->listener);}}
int wena_server_runtime_start(WenaServerRuntime *r,WenaServerSettings *s,const char *path,const unsigned char *migration,size_t length,const char *hash,WenaSecurityStore *security,WenaHttpNow now,void *context){if(!r||r->running||!s||!security||!now)return 0;if(!wena_sqlite_open(path,migration,length,hash,&r->database))return 0;wena_sqlite_persistence_init(&r->persistence,r->database);wena_domain_adapter_init(&r->domain,wena_sqlite_persistence_apply,&r->persistence);wena_http_listener_set_security(&r->listener,security,now,context);wena_http_listener_set_domain_adapter(&r->listener,&r->domain);if(!wena_http_listener_start(&r->listener,s)){sqlite3_close(r->database);r->database=NULL;wena_http_listener_init(&r->listener);return 0;}r->running=1;return 1;}
void wena_server_runtime_stop(WenaServerRuntime *r,WenaServerSettings *s){if(!r)return;wena_http_listener_stop(&r->listener,s);if(r->database){sqlite3_close(r->database);r->database=NULL;}r->running=0;wena_http_listener_init(&r->listener);}
